def _nvperf_to_hgperf(name):
    """Convert an NvPerf identifier to its HgPerf equivalent.
    Applies prefix replacements (NVPERF_ -> HGPERF_, NVPW_ -> HGPW_,
    NVPA_ -> HGPA_) then in-token replacements (NVPAStatus -> HGPAStatus,
    NVLRX -> HGLRX, NVLTX -> HGLTX).
    """
    result = name
    result = result.replace("NVPERF_", "HGPERF_")
    result = result.replace("NVPW_", "HGPW_")
    result = result.replace("NVPA_", "HGPA_")
    result = result.replace("NVPAStatus", "HGPAStatus")
    result = result.replace("NVLRX", "HGLRX")
    result = result.replace("NVLTX", "HGLTX")
    return result

CUDA_NVPERF_IDENTIFIER_MAP = collections.OrderedDict(
    (name, _nvperf_to_hgperf(name)) for name in _NVPERF_IDENTIFIERS
)

